/**
 * 取得 KIN 資料（支援隨機選擇 SetA/SetB）
 * @param {string} theme - 主題 key (financial/career/growth/health/relationship)
 * @param {number|string} kinId - KIN 編號 (1-260)
 * @returns {object} - { synchronicMessage, alignment, grounding }
 */
function getKinThemeData(theme, kinId) {
  const themeData = kinDataByTheme[theme];
  if (!themeData) return null;

  const kinStr = kinId.toString();

  // 如果有 setB，按 KIN + 日期隨機選擇
  if (themeData.setB) {
    // 基於 KIN 編號 + 今日日期產生偽隨機
    // 同一天內同一 KIN 固定，隔天可能不同
    const k = parseInt(kinId);
    const today = new Date();
    const dateNum = today.getFullYear() * 10000 + (today.getMonth() + 1) * 100 + today.getDate();
    const hash = ((k * 31) ^ (dateNum * 17) ^ ((k + dateNum) >> 2)) % 100;
    const useSetB = (hash < 50);

    return useSetB ? themeData.setB[kinStr] : themeData.setA[kinStr];
  }

  return themeData.setA[kinStr];
}

/**
 * 強制取得特定套的資料
 * @param {string} theme - 主題 key
 * @param {number|string} kinId - KIN 編號
 * @param {string} set - 'A' 或 'B'
 * @returns {object}
 */
function getKinThemeDataBySet(theme, kinId, set) {
  const themeData = kinDataByTheme[theme];
  if (!themeData) return null;

  const kinStr = kinId.toString();
  const setKey = set.toUpperCase() === 'B' ? 'setB' : 'setA';

  return themeData[setKey] ? themeData[setKey][kinStr] : themeData.setA[kinStr];
}
